    kind: int | None = Field(default=None, description='The type (kind) of charge.', json_schema_extra={'xml': 'element', 'wrapper': 'ChargeKind'})
    value: int | None = Field(default=None, description='A monetary charge.', json_schema_extra={'xml': 'element', 'required': True})
    Charge_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
