class DutyCycle(SepBase):
    """Duty cycle control is a device specific issue and is managed by the device.  The duty cycle of the device under control should span the shortest practical time period in accordance with the nature of the device under control and the intent of the request for demand reduction.  The default factory setting SHOULD be three minutes for each 10% of duty cycle.  This indicates that the default time period over which a duty cycle is applied is 30 minutes, meaning a 10% duty cycle would cause a device to be ON for 3 minutes.   The “off state” SHALL precede the “on state”. " """

    normalValue: int | None = Field(default=None, description='Contains the maximum On state duty cycle applied by the end device, as a percentage of time. The field not present indicates that this field has not been used by the end device.', json_schema_extra={'xml': 'element', 'required': True})
    DutyCycle_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    other_element: list[Any] = Field(default_factory=list, json_schema_extra={'xml': 'any'})
    any_attributes: dict[str, str] | None = Field(default=None, json_schema_extra={'xml': 'any'})


class EnvironmentalCost(SepBase):
    """Provides alternative or secondary price information for the relevant RateComponent.  Supports jurisdictions that seek to convey the environmental price per unit of the specified commodity not expressed in currency. Implementers and consumers can use this attribute to prioritize operations of their devices (e.g., PEV charging during times of high availability of renewable electricity resources). " """

    amount: int | None = Field(default=None, description='The estimated or actual environmental or other cost, per commodity unit defined by the ReadingType, for this RateComponent (e.g., grams of carbon dioxide emissions each per kWh).', json_schema_extra={'xml': 'element', 'required': True})
    costKind: int | None = Field(default=None, description='The kind of cost referred to in the amount.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'CostKindType'})
    costLevel: int | None = Field(default=None, description='The relative level of the amount attribute. In conjunction with numCostLevels, this attribute informs a device of the relative scarcity of the amount attribute (e.g., a high or low availability of renewable generation). numCostLevels and costLevel values SHALL ascend in order of scarcity, where "0" signals the lowest relative cost and higher values signal increasing cost. For example, if numCostLevels is equal to “3,” then if the lowest relative costLevel were equal to “0,” devices would assume this is the lowest relative period to operate. Likewise, if the costLevel in the next TimeTariffInterval instance is equal to “1,” then the device would assume it is relatively more expensive, in environmental terms, to operate during this TimeTariffInterval instance than the previous one. There is no limit to the number of relative price levels other than that indicated in the attribute type, but for practicality, service providers should strive for simplicity and recognize the diminishing returns derived from increasing the numCostLevel value greater than four.', json_schema_extra={'xml': 'element', 'required': True})
    numCostLevels: int | None = Field(default=None, description='The number of all relative cost levels. In conjunction with costLevel, numCostLevels signals the relative scarcity of the commodity for the duration of the TimeTariffInterval instance (e.g., a relative indication of cost). This is useful in providing context for nominal cost signals to consumers or devices that might see a range of amount values from different service providres or from the same service provider.', json_schema_extra={'xml': 'element', 'required': True})
    EnvironmentalCost_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    other_element: list[Any] = Field(default_factory=list, json_schema_extra={'xml': 'any'})
    any_attributes: dict[str, str] | None = Field(default=None, json_schema_extra={'xml': 'any'})


class EventStatus(SepBase):
    """Current status information relevant to a specific object.  The Status object is used to indicate the current status of an Event. Devices can read the containing resource (e.g. TextMessage) to get the most up to date status of the event.  Devices can also subscribe to a specific resource instance to get updates when any of its attributes change, including the Status object. " """

    currentStatus: int | None = Field(default=None, description='Field representing the current status type. 0 = Scheduled This status indicates that the event has been scheduled and the event has not yet started. The server SHALL set the event to this status when the event is first scheduled and persist until the event has become active or has been cancelled. For events with a start time less than or equal to the current time, this status SHALL never be indicated, the event SHALL start with a status of “Active”. 1 = Active This status indicates that the event is currently active, even if the event is known to be overlapped. The server SHALL set the event to this status when the event reaches its earliest Effective Start Time. 2 = Cancelled When events are cancelled, the Status.dateTime attribute SHALL be set to the time the cancellation occurred, which cannot be in the future. The server is responsible for maintaining the cancelled event in its collection for the duration of the original event, or until the server has run out of space and needs to store a new event. Client devices SHALL be aware of Cancelled events, determine if the Cancelled event applies to them, and cancel the event immediately if applicable. 3 = Cancelled with Randomization The server is responsible for maintaining the cancelled event in its collection for the duration of the Effective Scheduled Period. Client devices SHALL be aware of Cancelled with Randomization events, determine if the Cancelled event applies to them, and cancel the event immediately, using the larger of (absolute value of randomizeStart) and (absolute value of randomizeDuration) as the end randomization, in seconds. This Status.type SHALL NOT be used with "regular" Events, only with specializations of RandomizableEvent. 4 = Superseded (DEPRECATED) SHALL NOT be used by servers, but clients should note that it may be used by servers compliant with previous revisions of IEEE 2030.5. 5 = Completed This status indicates that the event has completed. The server SHALL set the event to this status after the event\'s maximum Effective Scheduled Period if the event has not been cancelled and is still present on the server. Note that this status value was not present in revisions prior to IEEE 2030.5-2023. All other values reserved.', json_schema_extra={'xml': 'element', 'required': True})
    dateTime: int | None = Field(default=None, description='The dateTime attribute will provide a timestamp of when the current status was defined. dateTime SHALL be set to the time at which the status change occurred, not a time in the future or past.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    potentiallySuperseded: bool | None = Field(default=None, description='DEPRECATED SHALL be set to true.', json_schema_extra={'xml': 'element', 'required': True})
    potentiallySupersededTime: int | None = Field(default=None, description='DEPRECATED SHALL NOT be included by servers, but clients should note that it may be included by servers compliant with previous revisions of IEEE 2030.5.', json_schema_extra={'xml': 'element', 'wrapper': 'TimeType'})
    reason: str | None = Field(default=None, description='The Reason attribute allows a Service provider to provide a textual explanation of the status.', max_length=192, json_schema_extra={'xml': 'element', 'max_length': 192})
    EventStatus_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    other_element: list[Any] = Field(default_factory=list, json_schema_extra={'xml': 'any'})
    any_attributes: dict[str, str] | None = Field(default=None, json_schema_extra={'xml': 'any'})


