class Offset(SepBase):
    """If a temperature offset is sent that causes the heating or cooling temperature set point to exceed the limit boundaries that are programmed into the device, the device SHALL respond by setting the temperature at the limit.  If an EDC is being targeted at multiple devices or to a device that controls multiple devices (e.g., EMS), it can provide multiple Offset types within one EDC. For events with multiple Offset types, a client SHALL select the Offset that best fits their operating function. Alternatively, an event with a single Offset type can be targeted at an EMS in order to request a percentage load reduction on the average energy usage of the entire premise. An EMS SHOULD use the Metering function set to determine the initial load in the premise, reduce energy consumption by controlling devices at its disposal, and at the conclusion of the event, once again use the Metering function set to determine if the desired load reduction was achieved. " """

    coolingOffset: int | None = Field(default=None, description='The value change requested for the cooling offset, in degree C / 10. The value should be added to the normal set point for cooling, or if loadShiftForward is true, then the value should be subtracted from the normal set point.', json_schema_extra={'xml': 'element'})
    heatingOffset: int | None = Field(default=None, description='The value change requested for the heating offset, in degree C / 10. The value should be subtracted for heating, or if loadShiftForward is true, then the value should be added to the normal set point.', json_schema_extra={'xml': 'element'})
    loadAdjustmentPercentageOffset: int | None = Field(default=None, description='The value change requested for the load adjustment percentage. The value should be subtracted from the normal setting, or if loadShiftForward is true, then the value should be added to the normal setting.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCent'})
    Offset_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    other_element: list[Any] = Field(default_factory=list, json_schema_extra={'xml': 'any'})
    any_attributes: dict[str, str] | None = Field(default=None, json_schema_extra={'xml': 'any'})


