class SetPoint(SepBase):
    """The SetPoint object is used to apply specific temperature set points to a temperature control device. The values of the heatingSetpoint and coolingSetpoint attributes SHALL be calculated as follows: Cooling/Heating Temperature Set Point / 100 = temperature in degrees Celsius where -273.15°C &amp;lt;= temperature &amp;lt;= 327.67°C, corresponding to a Cooling and/or Heating Temperature Set Point. The maximum resolution this format allows is 0.01°C. The field not present in a Response indicates that this field has not been used by the end device. If a temperature is sent that exceeds the temperature limit boundaries that are programmed into the device, the device SHALL respond by setting the temperature at the limit."""

    coolingSetpoint: int | None = Field(default=None, description='This attribute represents the cooling temperature set point in degrees Celsius / 100. (Hundredths of a degree C)', json_schema_extra={'xml': 'element'})
    heatingSetpoint: int | None = Field(default=None, description='This attribute represents the heating temperature set point in degrees Celsius / 100. (Hundredths of a degree C)', json_schema_extra={'xml': 'element'})
    SetPoint_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    other_element: list[Any] = Field(default_factory=list, json_schema_extra={'xml': 'any'})
    any_attributes: dict[str, str] | None = Field(default=None, json_schema_extra={'xml': 'any'})


