    rtgAbnormalCategory: int | None = Field(default=None, description='Abnormal operating performance category as defined by IEEE 1547-2018. One of: 0 - not specified 1 - Category I 2 - Category II 3 - Category III All other values reserved.', json_schema_extra={'xml': 'element'})
    rtgMaxA: CurrentRMS | None = Field(default=None, description='Maximum continuous AC current capability of the DER, in Amperes (RMS).', json_schema_extra={'xml': 'element'})
    rtgMaxAh: AmpereHour | None = Field(default=None, description='Usable energy storage capacity of the DER, in AmpHours.', json_schema_extra={'xml': 'element'})
    rtgMaxChargeRateVA: ApparentPower | None = Field(default=None, description='Maximum apparent power charge rating in Volt-Amperes. May differ from the maximum apparent power rating.', json_schema_extra={'xml': 'element'})
    rtgMaxChargeRateW: ActivePower | None = Field(default=None, description='Maximum rate of energy transfer received by the storage DER, in Watts.', json_schema_extra={'xml': 'element'})
    rtgMaxDischargeRateVA: ApparentPower | None = Field(default=None, description='Maximum rate of apparent power discharge by the storage DER, in Volt-Amperes. May differ from the maximum apparent power rating (rtgMaxVA) as this is specific to storage.', json_schema_extra={'xml': 'element'})
    rtgMaxDischargeRateW: ActivePower | None = Field(default=None, description='Maximum rate of energy transfer delivered by the storage DER, in Watts. Required for combined generation/storage DERs (e.g. DERType == 83). May differ from the maximum active power rating (rtgMaxW) as this is specific to storage.', json_schema_extra={'xml': 'element'})
    rtgMaxV: VoltageRMS | None = Field(default=None, description='AC voltage maximum rating.', json_schema_extra={'xml': 'element'})
    rtgMaxVA: ApparentPower | None = Field(default=None, description='Maximum continuous apparent power output capability of the DER, in VA.', json_schema_extra={'xml': 'element'})
    rtgMaxVar: ReactivePower | None = Field(default=None, description='Maximum continuous reactive power delivered by the DER, in var.', json_schema_extra={'xml': 'element'})
    rtgMaxVarNeg: ReactivePower | None = Field(default=None, description='Maximum continuous reactive power received by the DER, in var. If absent, defaults to negative rtgMaxVar.', json_schema_extra={'xml': 'element'})
    rtgMaxW: ActivePower | None = Field(default=None, description='Maximum continuous active power output capability of the DER, in watts. Represents combined generation plus storage output if DERType == 83.', json_schema_extra={'xml': 'element', 'required': True})
    rtgMaxWh: WattHour | None = Field(default=None, description='Maximum energy storage capacity of the DER, in WattHours.', json_schema_extra={'xml': 'element'})
    rtgMinPFOverExcited: PowerFactor | None = Field(default=None, description='Minimum Power Factor displacement capability of the DER when injecting reactive power (over-excited); SHALL be a positive value between 0.0 (typically &amp;gt; 0.7) and 1.0, inclusive. If absent, defaults to unity.', json_schema_extra={'xml': 'element'})
    rtgMinPFUnderExcited: PowerFactor | None = Field(default=None, description='Minimum Power Factor displacement capability of the DER when absorbing reactive power (under-excited); SHALL be a positive value between 0.0 (typically &amp;gt; 0.7) and 1.0, inclusive. If absent, defaults to rtgMinPFOverExcited.', json_schema_extra={'xml': 'element'})
    rtgMinV: VoltageRMS | None = Field(default=None, description='AC voltage minimum rating.', json_schema_extra={'xml': 'element'})
    rtgNormalCategory: int | None = Field(default=None, description='Normal operating performance category as defined by IEEE 1547-2018. One of: 0 - not specified 1 - Category A 2 - Category B All other values reserved.', json_schema_extra={'xml': 'element'})
    rtgOverExcitedPF: PowerFactor | None = Field(default=None, description='Specified over-excited power factor.', json_schema_extra={'xml': 'element'})
    rtgOverExcitedW: ActivePower | None = Field(default=None, description='Active power rating in Watts at specified over-excited power factor (rtgOverExcitedPF). If present, rtgOverExcitedPF SHALL be present.', json_schema_extra={'xml': 'element'})
    rtgReactiveSusceptance: ReactiveSusceptance | None = Field(default=None, description='Reactive susceptance that remains connected to the Area EPS in the cease to energize and trip state.', json_schema_extra={'xml': 'element'})
    rtgUnderExcitedPF: PowerFactor | None = Field(default=None, description='Specified under-excited power factor.', json_schema_extra={'xml': 'element'})
    rtgUnderExcitedW: ActivePower | None = Field(default=None, description='Active power rating in Watts at specified under-excited power factor (rtgUnderExcitedPF). If present, rtgUnderExcitedPF SHALL be present.', json_schema_extra={'xml': 'element'})
    rtgVNom: VoltageRMS | None = Field(default=None, description='AC voltage nominal rating.', json_schema_extra={'xml': 'element'})
    type: int | None = Field(default=None, json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'DERType'})
    DERCapability_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


