class DERControlBase(SepBase):
    """Distributed Energy Resource (DER) Control Modes. " """

    opModConnect: bool | None = Field(default=None, description='Set DER as connected (true) or disconnected (false). Used in conjunction with ramp rate when re-connecting. Implies galvanic isolation. If galvanic isolation is not supported, a value of false implies de-energize. If both opModConnect and opModEnergize are present, the values are logically ANDed to determine the connection state.', json_schema_extra={'xml': 'element'})
    opModDeltaVar: ReactivePowerDeltaControlType | None = Field(default=None, description='Change in reactive power, in var. This DERControl mode is relative to the current reactive power input or output at the time the DERControl begins.', json_schema_extra={'xml': 'element'})
    opModDeltaW: ActivePowerDeltaControlType | None = Field(default=None, description='Change in active power, in Watts. This DERControl Mode is relative to the current active power input or output at the time the DERControl begins.', json_schema_extra={'xml': 'element'})
    opModEnergize: bool | None = Field(default=None, description='Set DER as energized (true) or de-energized (false). Used in conjunction with ramp rate when re-energizing. If both opModConnect and opModEnergize are present, the values are logically ANDed to determine the connection state.', json_schema_extra={'xml': 'element'})
    opModFixedPFAbsorbW: PowerFactorWithExcitationControlType | None = Field(default=None, description='The opModFixedPFAbsorbW function specifies a requested fixed Power Factor (PF) setting for when active power is being absorbed. The actual displacement SHALL be within the limits established by setMinPFOverExcited and setMinPFUnderExcited. If issued simultaneously with other reactive power DERControl Modes (e.g. opModFixedVar) the DERControl Mode resulting in least var magnitude SHOULD take precedence.', json_schema_extra={'xml': 'element'})
    opModFixedPFInjectW: PowerFactorWithExcitationControlType | None = Field(default=None, description='The opModFixedPFInjectW function specifies a requested fixed Power Factor (PF) setting for when active power is being injected. The actual displacement SHALL be within the limits established by setMinPFOverExcited and setMinPFUnderExcited. If issued simultaneously with other reactive power DERControl Modes (e.g. opModFixedVar) the DERControl Mode resulting in least var magnitude SHOULD take precedence.', json_schema_extra={'xml': 'element'})
    opModFixedV: int | None = Field(default=None, description='The opModFixedV function specifies a requested voltage setpoint, in %setVNom (in hundredths).', json_schema_extra={'xml': 'element', 'wrapper': 'SignedPerCentControlType', 'attributes': ['disabled']})
    opModFixedVar: FixedVarControlType | None = Field(default=None, description='The opModFixedVar function specifies the delivered or received reactive power setpoint. The context for the setpoint value is determined by refType and SHALL be one of %setMaxW, %setMaxVA, %setMaxVar, or %statVarAvail. If issued simultaneously with other reactive power DERControl Modes (e.g. opModFixedPFInjectW) the DERControl Mode resulting in least var magnitude SHOULD take precedence.', json_schema_extra={'xml': 'element'})
    opModFixedW: int | None = Field(default=None, description='The opModFixedW function specifies a requested received (e.g., charge) or delivered (e.g., discharge) active power setpoint, in %setMaxChargeRateW if negative value or %setMaxW or %setMaxDischargeRateW if positive value (in hundredths).', json_schema_extra={'xml': 'element', 'wrapper': 'SignedPerCentControlType', 'attributes': ['disabled']})
    opModFreqDroop: FreqDroopType | None = Field(default=None, description='Specifies a frequency-watt operation. This operation limits active power generation or consumption when the line frequency deviates from nominal by a specified amount.', json_schema_extra={'xml': 'element'})
    opModFreqWatt: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 0. The Frequency-Watt function limits active power generation or consumption when the line frequency deviates from nominal by a specified amount. The Frequency-Watt curve is specified as an array of Frequency-Watt pairs that are interpolated into a piecewise linear function with hysteresis. The x value of each pair specifies a frequency in Hz. The y value specifies a corresponding active power output in %setMaxW.', json_schema_extra={'xml': 'element'})
    opModGridConnectPermit: bool | None = Field(default=None, description='Permits (true) or disallows (false) a grid reconnection. This DERControl Mode is likely to be more useful for microgrid controllers.', json_schema_extra={'xml': 'element'})
    opModHFRTMayTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 1. The High Frequency Ride-Through (HFRT) function is specified by one or two duration-frequency curves that define the operating region under high frequency conditions. Each HFRT curve is specified by an array of duration-frequency pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given frequency in seconds). The y value of each pair specifies a frequency, in Hz. This DERControl Mode specifies the "may trip" region.', json_schema_extra={'xml': 'element'})
    opModHFRTMustTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 2. The High Frequency Ride-Through (HFRT) function is specified by a duration-frequency curve that defines the operating region under high frequency conditions. Each HFRT curve is specified by an array of duration-frequency pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given frequency in seconds). The y value of each pair specifies a frequency, in Hz. This DERControl Mode specifies the "must trip" region.', json_schema_extra={'xml': 'element'})
    opModHVRTMayTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 3. The High Voltage Ride-Through (HVRT) function is specified by one, two, or three duration-volt curves that define the operating region under high voltage conditions. Each HVRT curve is specified by an array of duration-volt pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given voltage in seconds). The y value of each pair specifies an effective percentage voltage, defined as ((locally measured voltage - setVRefOfs / setVRef). This DERControl Mode specifies the "may trip" region.', json_schema_extra={'xml': 'element'})
    opModHVRTMomentaryCessation: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 4. The High Voltage Ride-Through (HVRT) function is specified by duration-volt curves that define the operating region under high voltage conditions. Each HVRT curve is specified by an array of duration-volt pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given voltage in seconds). The y value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef). This DERControl Mode specifies the "momentary cessation" region.', json_schema_extra={'xml': 'element'})
    opModHVRTMustTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 5. The High Voltage Ride-Through (HVRT) function is specified by duration-volt curves that define the operating region under high voltage conditions. Each HVRT curve is specified by an array of duration-volt pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given voltage in seconds). The y value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef). This DERControl Mode specifies the "must trip" region.', json_schema_extra={'xml': 'element'})
    opModIslandPermit: bool | None = Field(default=None, description='Permits (true) or disallows (false) grid islanding. This DERControl Mode is likely to be more useful for microgrid controllers.', json_schema_extra={'xml': 'element'})
    opModLFRTMayTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 6. The Low Frequency Ride-Through (LFRT) function is specified by one or two duration-frequency curves that define the operating region under low frequency conditions. Each LFRT curve is specified by an array of duration-frequency pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given frequency in seconds). The y value of each pair specifies a frequency, in Hz. This DERControl Mode specifies the "may trip" region.', json_schema_extra={'xml': 'element'})
    opModLFRTMustTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 7. The Low Frequency Ride-Through (LFRT) function is specified by a duration-frequency curve that defines the operating region under low frequency conditions. Each LFRT curve is specified by an array of duration-frequency pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given frequency in seconds). The y value of each pair specifies a frequency, in Hz. This DERControl Mode specifies the "must trip" region.', json_schema_extra={'xml': 'element'})
    opModLVRTMayTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 8. The Low Voltage Ride-Through (LVRT) function is specified by one, two, or three duration-volt curves that define the operating region under low voltage conditions. Each LVRT curve is specified by an array of duration-volt pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given voltage in seconds). The y value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef). This DERControl Mode specifies the "may trip" region.', json_schema_extra={'xml': 'element'})
    opModLVRTMomentaryCessation: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 9. The Low Voltage Ride-Through (LVRT) function is specified by duration-volt curves that define the operating region under low voltage conditions. Each LVRT curve is specified by an array of duration-volt pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given voltage in seconds). The y value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef). This DERControl Mode specifies the "momentary cessation" region.', json_schema_extra={'xml': 'element'})
    opModLVRTMustTrip: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 10. The Low Voltage Ride-Through (LVRT) function is specified by duration-volt curves that define the operating region under low voltage conditions. Each LVRT curve is specified by an array of duration-volt pairs that will be interpolated into a piecewise linear function that defines an operating region. The x value of each pair specifies a duration (time at a given voltage in seconds). The y value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef). This DERControl Mode specifies the "must trip" region.', json_schema_extra={'xml': 'element'})
    opModMaxLimPctVAAbsorb: int | None = Field(default=None, description='The opModMaxLimPctVAAbsorb function sets the maximum apparent power absorption level at the electrical reference point as a percentage of set capacity (%setMaxChargeRateVA, in hundredths). If issued simultaneously with other active or reactive power modes/controls, this mode/control SHOULD take precedence.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCentControlType', 'attributes': ['disabled']})
    opModMaxLimPctVAInject: int | None = Field(default=None, description='The opModMaxLimPctVAInject function sets the maximum apparent power injection level at the electrical reference point as a percentage of set capacity (%setMaxVA, in hundredths). If issued simultaneously with other active or reactive power modes/controls, this mode/control SHOULD take precedence.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCentControlType', 'attributes': ['disabled']})
    opModMaxLimPctVarAbsorb: UnsignedFixedVarControlType | None = Field(default=None, description='The opModMaxLimPctVarAbsorb function sets the maximum reactive power absorption level at the electrical reference point as a percentage of set capacity (in hundredths). The context for the setpoint value is determined by refType and SHALL be one of %setMaxW, %setMaxVA, %setMaxVar, or %statVarAvail.', json_schema_extra={'xml': 'element'})
    opModMaxLimPctVarInject: UnsignedFixedVarControlType | None = Field(default=None, description='The opModMaxLimPctVarInject function sets the maximum reactive power injection level at the electrical reference point as a percentage of set capacity (in hundredths). The context for the setpoint value is determined by refType and SHALL be one of %setMaxW, %setMaxVA, %setMaxVar, or %statVarAvail.', json_schema_extra={'xml': 'element'})
    opModMaxLimPctWAbsorb: int | None = Field(default=None, description='The opModMaxLimPctWAbsorb function sets the maximum active power absorption level at the electrical reference point as a percentage of set capacity (%setMaxChargeRateW, in hundredths). This limitation may be met e.g. by increasing PV output or by decreasing active power used to charge associated storage or power other loads.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCentControlType', 'attributes': ['disabled']})
    opModMaxLimVarAbsorb: UnsignedReactivePowerControlType | None = Field(default=None, description='The opModMaxLimVarAbsorb function sets the maximum reactive power absorption level at the electrical reference point.', json_schema_extra={'xml': 'element'})
    opModMaxLimVarInject: UnsignedReactivePowerControlType | None = Field(default=None, description='The opModMaxLimVarInject function sets the maximum reactive power injection level at the electrical reference point.', json_schema_extra={'xml': 'element'})
    opModMaxLimW: int | None = Field(default=None, description='The opModMaxLimW function sets the maximum active power generation level at the electrical reference point as a percentage of set capacity (%setMaxW, in hundredths). This limitation may be met e.g. by reducing PV output or by using excess PV output to charge associated storage or power other loads. Note: opModMaxLimW is inconsistently named for historical reasons as its units are PerCent instead of ActivePower. Its preferred name would have been opModMaxLimPctWInject.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCentControlType', 'attributes': ['disabled']})
    opModMaxLimWAbsorb: UnsignedActivePowerControlType | None = Field(default=None, description='The opModMaxLimWAbsorb function sets the maximum active power absorption level at the electrical reference point. This limitation may be met e.g. by increasing PV output or by decreasing active power used to charge associated storage or power other loads.', json_schema_extra={'xml': 'element'})
    opModMaxLimWInject: UnsignedActivePowerControlType | None = Field(default=None, description='The opModMaxLimWInject function sets the maximum active power generation level at the electrical reference point. This limitation may be met e.g. by reducing PV output or by using excess PV output to charge associated storage or power other loads.', json_schema_extra={'xml': 'element'})
    opModTargetV: VoltageRMSControlType | None = Field(default=None, description='Target output power, in Volts.', json_schema_extra={'xml': 'element'})
    opModTargetVar: ReactivePowerControlType | None = Field(default=None, description='Target reactive power, in var. This DERControl Mode is likely to be more useful for aggregators, as individual DERs may not be able to maintain a target setting.', json_schema_extra={'xml': 'element'})
    opModTargetW: ActivePowerControlType | None = Field(default=None, description='Target output power, in Watts. This DERControl Mode is likely to be more useful for aggregators, as individual DERs may not be able to maintain a target setting.', json_schema_extra={'xml': 'element'})
    opModVoltVar: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 11. The static volt-var function provides over- or under-excited var compensation as a function of measured voltage. The volt-var curve is specified as an array of volt-var pairs that are interpolated into a piecewise linear function with hysteresis. The x value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef) and SHOULD support a domain of at least 0 - 135. If VRef is present in DERCurve, then the x value of each pair is additionally multiplied by (VRef / 10000). The y value specifies a target var output interpreted as a signed percentage (-100 to 100). The meaning of the y value is determined by yRefType and must be one of %setMaxW, %setMaxVA, %setMaxVar, or %statVarAvail.', json_schema_extra={'xml': 'element'})
    opModVoltWatt: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 12. The Volt-Watt varies active power as a function of measured voltage. The Volt-Watt curve is specified as an array of Volt-Watt pairs that are interpolated into a piecewise linear function with hysteresis. The x value of each pair specifies an effective percent voltage, defined as ((locally measured voltage - setVRefOfs) / setVRef) and SHOULD support a domain of at least 0 - 135. The y value specifies an active power setting interpreted as a signed percentage (-100 to 100). The meaning of the y value is determined by yRefType and must be one of %setMaxW or %statWAvail.', json_schema_extra={'xml': 'element'})
    opModWattPF: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 13. The Watt-PF function varies Power Factor (PF) as a function of delivered or received active power. The Watt-PF curve is specified as an array of Watt- PF coordinates that are interpolated into a piecewise linear function with hysteresis. The x value of each pair specifies a watt setting in %setMaxChargeRateW if negative value or %setMaxW or %setMaxDischargeRateW if positive value, (-100 to 100). The PF output setting is an unsigned displacement in the y value with the excitation set according to the excitation boolean. These settings are not expected to be updated very often during the life of the installation, therefore only a single curve is required. If issued simultaneously with other reactive power DERControl Modes (e.g. opModFixedPFInjectW) the DERControl Mode resulting in least var magnitude SHOULD take precedence.', json_schema_extra={'xml': 'element'})
    opModWattVar: DERCurveLink | None = Field(default=None, description='Specify DERCurveLink for curveType == 14. The Watt-Var function varies vars as a function of delivered or received active power. The Watt-Var curve is specified as an array of Watt-Var pairs that are interpolated into a piecewise linear function with hysteresis. The x value of each pair specifies a watt setting in %setMaxChargeRateW if negative value or %setMaxW or %setMaxDischargeRateW if positive value, (-100 to 100). The y value specifies a target var output interpreted as a signed percentage (-100 to 100). The meaning of the y value is determined by yRefType and must be one of %setMaxW, %setMaxVA, %setMaxVar, or %statVarAvail.', json_schema_extra={'xml': 'element'})
    rampTms: int | None = Field(default=None, description='Requested ramp time, in hundredths of a second, for the device to transition from the current DERControl Mode(s) to the new DERControl Mode(s). If absent, use default ramp rate (setGradW). Resolution is 1/100 sec.', json_schema_extra={'xml': 'element'})
    DERControlBase_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    other_element: list[Any] = Field(default_factory=list, json_schema_extra={'xml': 'any'})
    any_attributes: dict[str, str] | None = Field(default=None, json_schema_extra={'xml': 'any'})


