class File(Resource):
    """This resource contains various meta-data describing a file's characteristics.  The meta-data provides general file information and also is used to support filtered queries of file lists " """

    activateTime: int | None = Field(default=None, description='This element SHALL be set to the date/time at which this file is activated. If the activation time is less than or equal to current time, the LD SHALL immediately place the file into the activated state (in the case of a firmware file, the file is now the running image). If the activation time is greater than the current time, the LD SHALL wait until the specified activation time is reached, then SHALL place the file into the activated state. Omission of this element means that the LD SHALL NOT take any action to activate the file until a subsequent GET to this File resource provides an activateTime.', json_schema_extra={'xml': 'element', 'wrapper': 'TimeType'})
    fileURI: str | None = Field(default=None, description='This element SHALL be set to the URI location of the file binary artifact. This is the BLOB (binary large object) that is actually loaded by the LD', json_schema_extra={'xml': 'element', 'required': True})
    lFDI: str | None = Field(default=None, description='This element SHALL be set to the LFDI of the device for which this file in targeted.', json_schema_extra={'xml': 'element', 'format': 'base16', 'max_length': 20})
    mfHwVer: str | None = Field(default=None, description='This element SHALL be set to the hardware version for which this file is targeted.', max_length=32, json_schema_extra={'xml': 'element', 'max_length': 32})
    mfID: int | None = Field(default=None, description="This element SHALL be set to the manufacturer's Private Enterprise Number (assigned by IANA).", json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'PENType'})
    mfModel: str | None = Field(default=None, description='This element SHALL be set to the manufacturer model number for which this file is targeted. The syntax and semantics are left to the manufacturer.', max_length=32, json_schema_extra={'xml': 'element', 'required': True, 'max_length': 32})
    mfSerNum: str | None = Field(default=None, description='This element SHALL be set to the manufacturer serial number for which this file is targeted. The syntax and semantics are left to the manufacturer.', max_length=32, json_schema_extra={'xml': 'element', 'max_length': 32})
    mfVer: str | None = Field(default=None, description='This element SHALL be set to the software version information for this file. The syntax and semantics are left to the manufacturer.', max_length=16, json_schema_extra={'xml': 'element', 'required': True, 'max_length': 16})
    size: int | None = Field(default=None, description='This element SHALL be set to the total size (in bytes) of the file referenced by fileURI.', json_schema_extra={'xml': 'element', 'required': True})
    type: str | None = Field(default=None, json_schema_extra={'xml': 'element', 'required': True, 'format': 'base16', 'max_length': 2})
    File_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


