    details: str | None = Field(default=None, description='Human readable text that MAY be used to transmit additional details about the event. A host MAY remove this field when received.', max_length=32, json_schema_extra={'xml': 'element', 'max_length': 32})
    extendedData: int | None = Field(default=None, description='May be used to transmit additional details about the event.', json_schema_extra={'xml': 'element'})
    functionSet: int | None = Field(default=None, description='If the profileID indicates this is IEEE 2030.5, the functionSet is defined by IEEE 2030.5 and SHALL be one of the values from the table below (IEEE 2030.5 function set identifiers). If the profileID is anything else, the functionSet is defined by the identified profile. 0 General (not specific to a function set) 1 Subscription/Notification 2 End Device 3 Function Set Assignments 4 Response 5 Demand Response and Load Control 6 Metering 7 Pricing 8 Messaging 9 Billing 10 Prepayment 11 Distributed Energy Resources 12 Time 13 Software Download 14 Device Information 15 Power Status 16 Network Status 17 Log Event 18 Configuration 19 Security 20 Self Device 21 Flow Reservation 22 Metering Mirror 23 Aggregation 24 Proxied Device All other values are reserved.', json_schema_extra={'xml': 'element', 'required': True})
    logEventCode: int | None = Field(default=None, description='An 8 bit unsigned integer. logEventCodes are scoped to a profile and a function set. If the profile is IEEE 2030.5, the logEventCode is defined by IEEE 2030.5 within one of the function sets of IEEE 2030.5. If the profile is anything else, the logEventCode is defined by the specified profile.', json_schema_extra={'xml': 'element', 'required': True})
    logEventID: int | None = Field(default=None, description='This 16-bit value, combined with createdDateTime, profileID, and logEventPEN, should provide a reasonable level of uniqueness.', json_schema_extra={'xml': 'element', 'required': True})
    logEventPEN: int | None = Field(default=None, description='The Private Enterprise Number(PEN) of the entity that defined the profileID, functionSet, and logEventCode of the logEvent. IEEE 2030.5-assigned logEventCodes SHALL use the IEEE 2030.5 PEN. Combinations of profileID, functionSet, and logEventCode SHALL have unique meaning within a logEventPEN and are defined by the owner of the PEN.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'PENType'})
    profileID: int | None = Field(default=None, description='The profileID identifies which profile (HA, BA, SE, etc) defines the following event information. 0 Not profile specific. 1 Vendor Defined 2 IEEE 2030.5 3 Home Automation 4 Building Automation All other values are reserved.', json_schema_extra={'xml': 'element', 'required': True})
    LogEvent_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


