class ReadingType(Resource):
    """Type of data conveyed by a specific Reading.  See IEC 61968 Part 9 Annex C for full definitions of these values. " """

    accumulationBehaviour: int | None = Field(default=None, description='The “accumulation behaviour” indicates how the value is represented to accumulate over time.', json_schema_extra={'xml': 'element', 'wrapper': 'AccumulationBehaviourType'})
    calorificValue: UnitValueType | None = Field(default=None, description='The amount of heat generated when a given mass of fuel is completely burned. The CalorificValue is used to convert the measured volume or mass of gas into kWh. The CalorificValue attribute represents the current active value.', json_schema_extra={'xml': 'element'})
    commodity: int | None = Field(default=None, description='Indicates the commodity applicable to this ReadingType.', json_schema_extra={'xml': 'element', 'wrapper': 'CommodityType'})
    conversionFactor: UnitValueType | None = Field(default=None, description='Accounts for changes in the volume of gas based on temperature and pressure. The ConversionFactor attribute represents the current active value. The ConversionFactor is dimensionless. If not present, no conversion is applied. A price server can advertise a new/different value at any time.', json_schema_extra={'xml': 'element'})
    dataQualifier: int | None = Field(default=None, description='The data type can be used to describe a salient attribute of the data. Possible values are average, absolute, and etc.', json_schema_extra={'xml': 'element', 'wrapper': 'DataQualifierType'})
    flowDirection: int | None = Field(default=None, description='Anything involving current might have a flow direction.', json_schema_extra={'xml': 'element', 'wrapper': 'FlowDirectionType'})
    intervalLength: int | None = Field(default=None, description='Default interval length specified in seconds.', json_schema_extra={'xml': 'element'})
    kind: int | None = Field(default=None, description='Compound class that contains kindCategory and kindIndex', json_schema_extra={'xml': 'element', 'wrapper': 'KindType'})
    maxNumberOfIntervals: int | None = Field(default=None, description='To be populated for mirrors of interval data to set the expected number of intervals per ReadingSet. Servers may discard intervals received that exceed this number.', json_schema_extra={'xml': 'element'})
    numberOfConsumptionBlocks: int | None = Field(default=None, description='Number of consumption blocks. 0 means not applicable, and is the default if not specified. The value needs to be at least 1 if any actual prices are provided.', json_schema_extra={'xml': 'element'})
    numberOfTouTiers: int | None = Field(default=None, description='The number of TOU tiers that can be used by any resource configured by this ReadingType. Servers SHALL populate this value with the largest touTier value that will &lt;i&gt;ever&lt;/i&gt; be used while this ReadingType is in effect. Servers SHALL set numberOfTouTiers equal to the number of standard TOU tiers plus the number of CPP tiers that may be used while this ReadingType is in effect. Servers SHALL specify a value between 0 and 255 (inclusive) for numberOfTouTiers (servers providing flat rate pricing SHOULD set numberOfTouTiers to 0, as in practice there is no difference between having no tiers and having one tier).', json_schema_extra={'xml': 'element'})
    phase: int | None = Field(default=None, description='Contains phase information associated with the type.', json_schema_extra={'xml': 'element', 'wrapper': 'PhaseCode'})
    powerOfTenMultiplier: int | None = Field(default=None, description='Indicates the power of ten multiplier applicable to the unit of measure of this ReadingType.', json_schema_extra={'xml': 'element', 'wrapper': 'PowerOfTenMultiplierType'})
    subIntervalLength: int | None = Field(default=None, description='Default sub-interval length specified in seconds for Readings of ReadingType. Some demand calculations are done over a number of smaller intervals. For example, in a rolling demand calculation, the demand value is defined as the rolling sum of smaller intervals over the intervalLength. The subintervalLength is the length of the smaller interval in this calculation. It SHALL be an integral division of the intervalLength. The number of sub-intervals can be calculated by dividing the intervalLength by the subintervalLength.', json_schema_extra={'xml': 'element'})
    supplyLimit: int | None = Field(default=None, description='Reflects the supply limit set in the meter. This value can be compared to the Reading value to understand if limits are being approached or exceeded. Units follow the same definition as in this ReadingType.', le=281474976710655, json_schema_extra={'xml': 'element', 'max_inclusive': 281474976710655})
    tieredConsumptionBlocks: bool | None = Field(default=None, description='Specifies whether or not the consumption blocks are differentiated by TOUTier or not. Default is false, if not specified. true = consumption accumulated over individual tiers false = consumption accumulated over all tiers', json_schema_extra={'xml': 'element'})
    uom: int | None = Field(default=None, description='Indicates the measurement type for the units of measure for the readings of this type.', json_schema_extra={'xml': 'element', 'wrapper': 'UomType'})
    ReadingType_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


