class Time(Resource):
    """Contains the representation of time, constantly updated. " """

    currentTime: int | None = Field(default=None, description='The current time, in the format defined by TimeType.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    dstEndTime: int | None = Field(default=None, description='Time at which daylight savings ends (dstOffset no longer applied). Result of dstEndRule calculation.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    dstOffset: int | None = Field(default=None, description='Daylight savings time offset from local standard time. A typical practice is advancing clocks one hour when daylight savings time is in effect, which would result in a positive dstOffset. If dstOffset is 0, dstStartTime and dstEndTime SHALL be ignored.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeOffsetType'})
    dstStartTime: int | None = Field(default=None, description='Time at which daylight savings begins (apply dstOffset). Result of dstStartRule calculation.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    localTime: int | None = Field(default=None, description='Local time: localTime = currentTime + tzOffset (+ dstOffset when in effect).', json_schema_extra={'xml': 'element', 'wrapper': 'TimeType'})
    quality: int | None = Field(default=None, description='Metric indicating the quality of the time source from which the service acquired time. Lower (smaller) quality enumeration values are assumed to be more accurate. 3 - time obtained from external authoritative source such as NTP 4 - time obtained from level 3 source 5 - time manually set or obtained from level 4 source 6 - time obtained from level 5 source 7 - time intentionally uncoordinated All other values are reserved for future use.', json_schema_extra={'xml': 'element', 'required': True})
    tzOffset: int | None = Field(default=None, description='Local time zone offset from currentTime. Does not include any daylight savings time offsets. For American time zones, a negative tzOffset SHALL be used (eg, EST = GMT-5 which is -18000).', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeOffsetType'})
    Time_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    pollRate: int | None = Field(default=None, description='The default polling rate for this function set (this resource and all resources below), in seconds. If not specified, a default of 900 seconds (15 minutes) is used. Clients SHOULD poll the resources of this function set every pollRate seconds.', json_schema_extra={'xml': 'attribute'})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


