class UsagePointBase(IdentifiedObject):
    """Logical point on a network at which consumption or production is either physically measured (e.g. metered) or estimated (e.g. unmetered street lights).  A container for associating ReadingType, Readings and ReadingSets. " """

    roleFlags: str | None = Field(default=None, description='Specifies the roles that apply to the usage point.', json_schema_extra={'xml': 'element', 'required': True, 'format': 'base16', 'wrapper': 'RoleFlagsType'})
    serviceCategoryKind: int | None = Field(default=None, description='The kind of service provided by this usage point.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'ServiceKind'})
    status: int | None = Field(default=None, description='Specifies the current status of the service at this usage point. 0 = off 1 = on', json_schema_extra={'xml': 'element', 'required': True})
    UsagePointBase_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})


