class AbstractDevice(SubscribableResource):
    """Abstract asset container for devices.  Contains information about a device/entity. " """

    AggregatedDeviceListLink: _T_AggregatedDeviceListLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    AggregationPriorityLink: _T_AggregationPriorityLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    ConfigurationLink: _T_ConfigurationLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    DERListLink: _T_DERListLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    deviceCategory: str | None = Field(default=None, description='This field is for use in devices that can adjust energy usage (e.g., demand response, distributed energy resources). For devices that do not respond to EndDeviceControls or DERControls (for instance, an ESI), this field should not have any bits set.', json_schema_extra={'xml': 'element', 'format': 'base16', 'wrapper': 'DeviceCategoryType'})
    DeviceInformationLink: _T_DeviceInformationLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    DeviceStatusLink: _T_DeviceStatusLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    distribution: int | None = Field(default=None, description='When representing an aggregation of multiple devices, specifies how controls SHALL be distributed among members of the aggregation. If not specified, a default of 0 (Not Applicable / Unspecified) is used.', json_schema_extra={'xml': 'element', 'wrapper': 'AggregationDistributionType'})
    FileStatusLink: _T_FileStatusLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    IPInterfaceListLink: _T_IPInterfaceListLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    lFDI: str | None = Field(default=None, description='Long form of device identifier. See the Security section for additional details. Beginning with IEEE 2030.5-2023, this field SHALL be included. Note that this field is optional in revisions of IEEE 2030.5 prior to IEEE 2030.5-2023.', json_schema_extra={'xml': 'element', 'format': 'base16', 'max_length': 20})
    LoadShedAvailabilityListLink: _T_LoadShedAvailabilityListLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    LogEventListLink: _T_LogEventListLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    phase: int | None = Field(default=None, description='Indicates the electrical phase(s) on which this entity is connected.', json_schema_extra={'xml': 'element', 'wrapper': 'PhaseCode'})
    PowerStatusLink: _T_PowerStatusLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    sFDI: int | None = Field(default=None, description='Short form of device identifier, WITH the checksum digit. See the Security section for additional details.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'SFDIType'})
    AbstractDevice_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})


class AccountBalance(Resource):
    """AccountBalance contains the regular credit and emergency credit balance for this given service or commodity prepay instance.  It may also contain status information concerning the balance data. " """

    availableCredit: AccountingUnit | None = Field(default=None, description='AvailableCredit shows the balance of the sum of credits minus the sum of charges. In a Central Wallet mode this value may be passed down to the Prepayment server via an out-of-band mechanism. In Local or ESI modes, this value may be calculated based upon summation of CreditRegister transactions minus consumption charges calculated using Metering (and possibly Pricing) function set data. This value may be negative; for instance, if disconnection is prevented due to a Supply Interruption Override.', json_schema_extra={'xml': 'element', 'required': True})
    creditStatus: int | None = Field(default=None, description='CreditStatus identifies whether the present value of availableCredit is considered OK, low, exhausted, or negative.', json_schema_extra={'xml': 'element', 'wrapper': 'CreditStatusType'})
    emergencyCredit: AccountingUnit | None = Field(default=None, description='EmergencyCredit is the amount of credit still available for the given service or commodity prepayment instance. If both availableCredit and emergyCredit are exhausted, then service will typically be disconnected.', json_schema_extra={'xml': 'element'})
    emergencyCreditStatus: int | None = Field(default=None, description='EmergencyCreditStatus identifies whether the present value of emergencyCredit is considered OK, low, exhausted, or negative.', json_schema_extra={'xml': 'element', 'wrapper': 'CreditStatusType'})
    AccountBalance_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


class AggregationPriority(IdentifiedObject):
    """Contains the order in which an aggregation with a priority distribution is to be prioritized.  If an aggregation has a distribution of Priority, then this resource SHALL be present. If an aggregation does not have a distribution of Priority, then this resource SHALL NOT be present. PriorityData SHALL be listed in order of priority, with the highest priority listed first. Note that if there are a large number of PriorityData, then  this resource could grow large. Devices SHOULD use Range / Content-Range for transferring large resources as well as HTTP HEAD or other HTTP mechanisms to determine the size of the resource."""

    PriorityData: list[_T_PriorityData] = Field(default_factory=list, json_schema_extra={'xml': 'element', 'min_occurs': 1})
    AggregationPriority_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


