class CreditRegister(IdentifiedObject):
    """CreditRegister instances define a credit-modifying transaction.  Typically this would be a credit-adding transaction, but may be a subtracting transaction (perhaps in response to an out-of-band debt signal). " """

    creditAmount: AccountingUnit | None = Field(default=None, description='CreditAmount is the amount of credit being added by a particular CreditRegister transaction. Negative values indicate that credit is being subtracted.', json_schema_extra={'xml': 'element', 'required': True})
    creditType: int | None = Field(default=None, description='CreditType indicates whether the credit transaction applies to regular or emergency credit.', json_schema_extra={'xml': 'element', 'wrapper': 'CreditTypeType'})
    effectiveTime: int | None = Field(default=None, description='EffectiveTime identifies the time at which the credit transaction goes into effect. For credit addition transactions, this is typically the moment at which the transaction takes place. For credit subtraction transactions, (e.g., non-fuel debt recovery transactions initiated from a back-haul or ESI) this may be a future time at which credit is deducted.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    token: str | None = Field(default=None, description='Token is security data that authenticates the legitimacy of the transaction. The details of this token are not defined by IEEE 2030.5. How a Prepayment server handles this field is left as vendor specific implementation or will be defined by one or more other standards.', max_length=32, json_schema_extra={'xml': 'element', 'required': True, 'max_length': 32})
    CreditRegister_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


class DERAvailability(SubscribableResource):
    """Indicates current reserve status. " """

    availabilityDuration: int | None = Field(default=None, description='Indicates number of seconds the DER will be able to deliver active power at the reservePercent level.', json_schema_extra={'xml': 'element'})
    maxChargeDuration: int | None = Field(default=None, description='Indicates number of seconds the DER will be able to receive active power at the reserveChargePercent level.', json_schema_extra={'xml': 'element'})
    readingTime: int | None = Field(default=None, description='The timestamp when the DER availability was last updated.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    reserveChargePercent: int | None = Field(default=None, description='Percent of continuous received active power (%setMaxChargeRateW) that is estimated to be available in reserve.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCent'})
    reservePercent: int | None = Field(default=None, description='Percent of continuous delivered active power (%setMaxW) that is estimated to be available in reserve.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCent'})
    statVarAbsorbAvail: UnsignedReactivePower | None = Field(default=None, description='Estimated reserve reactive power for absorption / reception, in var. This value is equal to (estimated maximum possible absorbed / received vars at readingTime) - (current vars at readingTime).', json_schema_extra={'xml': 'element'})
    statVarAvail: ReactivePower | None = Field(default=None, description='Estimated reserve reactive power for injection / delivery, in var. This value is equal to (estimated maximum possible injected / delivered vars at readingTime) - (current vars at readingTime). Note that this value SHALL always be positive (defined as ReactivePower for legacy reasons).', json_schema_extra={'xml': 'element'})
    statWAbsorbAvail: UnsignedActivePower | None = Field(default=None, description='Estimated reserve active power for absorption / reception, in watts. This value is equal to (estimated maximum possible input at readingTime) - (current input at readingTime). Note that "current input" is defined to be greater than or equal to zero (not negative).', json_schema_extra={'xml': 'element'})
    statWAvail: ActivePower | None = Field(default=None, description='Estimated reserve active power for injection / delivery, in watts. This value is equal to (estimated maximum possible output at readingTime) - (current output at readingTime). Note that this value SHALL always be positive (defined as ActivePower for legacy reasons). Also note that "current output" is defined to be greater than or equal to zero (not negative).', json_schema_extra={'xml': 'element'})
    DERAvailability_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


class DERControlResponse(Response):
    """A response to a DERControl. " """

    modesResponded: str | None = Field(default=None, description='Indicates individual DERControl Modes for which the DERControlResponse applies. This field SHALL be present in DERControlResponse complying to this revision of IEEE 2030.5. However, it should be noted that in previous revisions of IEEE 2030.5 this field was not defined. When the field is not present, the individual DERControl Modes for which the DERControlResponse applies is ambiguous.', json_schema_extra={'xml': 'element', 'format': 'base16', 'wrapper': 'DERControlType'})
    modesResponded2: str | None = Field(default=None, description='Indicates additional individual DERControl Modes for which the DERControlResponse applies. It should be noted that in previous revisions of IEEE 2030.5 this field was not defined. When the field is not present, the additional individual DERControl Modes for which the DERControlResponse applies is none (as none of those DERControl Modes existed in previous revisions of IEEE 2030.5).', json_schema_extra={'xml': 'element', 'format': 'base16', 'wrapper': 'DERControlType2'})
    DERControlResponse_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


class DERCurve(IdentifiedObject):
    """DER related curves such as Volt-Var DERControl Mode curves.  Relationship between an independent variable (X-axis) and a dependent variable (Y-axis). " """

    autonomousVRefEnable: bool | None = Field(default=None, description='If the curveType is opModVoltVar, then this field MAY be present. If the curveType is not opModVoltVar, then this field SHALL NOT be present. Enable/disable autonomous vRef adjustment. When enabled, the Volt-Var curve characteristic SHALL be adjusted autonomously as vRef changes and autonomousVRefTimeConstant SHALL be present. If a DER is able to support the Volt-Var DERControl Mode but is unable to support autonomous vRef adjustment, then the DER SHALL execute the curve without autonomous vRef adjustment. If not specified, then the value is false.', json_schema_extra={'xml': 'element'})
    autonomousVRefTimeConstant: int | None = Field(default=None, description='If the curveType is opModVoltVar, then this field MAY be present. If the curveType is not opModVoltVar, then this field SHALL NOT be present. Adjustment range for vRef time constant, in hundredths of a second.', json_schema_extra={'xml': 'element'})
    creationTime: int | None = Field(default=None, description='The time at which the object was created.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    CurveData: list[_T_CurveData] = Field(default_factory=list, json_schema_extra={'xml': 'element', 'min_occurs': 1, 'max_occurs': 10})
    curveType: int | None = Field(default=None, description='Specifies the associated curve-based DERControl Mode.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'DERCurveType'})
    openLoopTms: int | None = Field(default=None, description='Open loop response time, the time to ramp up to 90% of the new target in response to the change in voltage, in hundredths of a second. Resolution is 1/100 sec. A value of 0 is used to mean no limit. When not present, the device SHOULD follow its default behavior.', json_schema_extra={'xml': 'element'})
    rampDecTms: int | None = Field(default=None, description='Decreasing ramp rate, interpreted as a percentage change in output capability limit per second (e.g. %setMaxW / sec). Resolution is in hundredths of a percent/second. A value of 0 means there is no limit. If absent, ramp rate defaults to setGradW.', json_schema_extra={'xml': 'element'})
    rampIncTms: int | None = Field(default=None, description='Increasing ramp rate, interpreted as a percentage change in output capability limit per second (e.g. %setMaxW / sec). Resolution is in hundredths of a percent/second. A value of 0 means there is no limit. If absent, ramp rate defaults to rampDecTms.', json_schema_extra={'xml': 'element'})
    rampPT1Tms: int | None = Field(default=None, description='The configuration parameter for a low-pass filter, PT1 is a time, in hundredths of a second, in which the filter will settle to 95% of a step change in the input value. Resolution is 1/100 sec.', json_schema_extra={'xml': 'element'})
    vRef: int | None = Field(default=None, description='If the curveType is opModVoltVar, then this field MAY be present. If the curveType is not opModVoltVar, then this field SHALL NOT be present. The nominal AC voltage (RMS) adjustment to the voltage curve points for Volt-Var curves.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCent'})
    xMultiplier: int | None = Field(default=None, description='Exponent for X-axis value.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'PowerOfTenMultiplierType'})
    yMultiplier: int | None = Field(default=None, description='Exponent for Y-axis value.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'PowerOfTenMultiplierType'})
    yRefType: int | None = Field(default=None, description='The Y-axis units context.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'DERUnitRefType'})
    DERCurve_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
