    setESRampTms: int | None = Field(default=None, description='Enter service ramp time, in hundredths of a second.', json_schema_extra={'xml': 'element'})
    setESRandomDelay: int | None = Field(default=None, description='Enter service randomized delay, in hundredths of a second.', json_schema_extra={'xml': 'element'})
    setGradW: int | None = Field(default=None, description='Set default rate of change (ramp rate) of active power output due to command or internal action, defined in %setWMax / second. Resolution is in hundredths of a percent/second. A value of 0 means there is no limit. Interpreted as a percentage change in output capability limit per second when used as a default ramp rate.', json_schema_extra={'xml': 'element', 'required': True})
    setMaxA: CurrentRMS | None = Field(default=None, description='AC current maximum. Maximum AC current in RMS Amperes.', json_schema_extra={'xml': 'element'})
    setMaxAh: AmpereHour | None = Field(default=None, description='Maximum usable energy storage capacity of the DER, in AmpHours. Note: this may be different from physical capability.', json_schema_extra={'xml': 'element'})
    setMaxChargeRateVA: ApparentPower | None = Field(default=None, description='Apparent power charge maximum. Maximum apparent power the DER can absorb from the grid in Volt-Amperes. May differ from the apparent power maximum (setMaxVA).', json_schema_extra={'xml': 'element'})
    setMaxChargeRateW: ActivePower | None = Field(default=None, description='Maximum rate of energy transfer received by the storage device, in Watts. Defaults to rtgMaxChargeRateW.', json_schema_extra={'xml': 'element'})
    setMaxDischargeRateVA: ApparentPower | None = Field(default=None, description='Apparent power discharge maximum. Maximum apparent power the storage DER can deliver to the grid in Volt-Amperes. May differ from the apparent power maximum (setMaxVA) as this is specific to storage.', json_schema_extra={'xml': 'element'})
    setMaxDischargeRateW: ActivePower | None = Field(default=None, description='Maximum rate of energy transfer delivered by the storage device, in Watts. Defaults to rtgMaxDischargeRateW. May differ from the active power maximum (setMaxW) as this is specific to storage.', json_schema_extra={'xml': 'element'})
    setMaxV: VoltageRMS | None = Field(default=None, description='AC voltage maximum setting.', json_schema_extra={'xml': 'element'})
    setMaxVA: ApparentPower | None = Field(default=None, description='Set limit for maximum apparent power capability of the DER (in VA). Defaults to rtgMaxVA.', json_schema_extra={'xml': 'element'})
    setMaxVar: ReactivePower | None = Field(default=None, description='Set limit for maximum reactive power injected/delivered by the DER (in var). SHALL be a positive value &amp;lt;= rtgMaxVar (default).', json_schema_extra={'xml': 'element'})
    setMaxVarNeg: ReactivePower | None = Field(default=None, description='Set limit for maximum reactive power absorbed/received by the DER (in var). If present, SHALL be a negative value &amp;gt;= rtgMaxVarNeg (default). If absent, defaults to negative setMaxVar.', json_schema_extra={'xml': 'element'})
    setMaxW: ActivePower | None = Field(default=None, description='Set limit for maximum active power capability of the DER (in W). Defaults to rtgMaxW.', json_schema_extra={'xml': 'element', 'required': True})
    setMaxWh: WattHour | None = Field(default=None, description='Maximum energy storage capacity of the DER, in WattHours. Note: this may be different from physical capability.', json_schema_extra={'xml': 'element'})
    setMinPFOverExcited: PowerFactor | None = Field(default=None, description='Set minimum Power Factor displacement limit of the DER when injecting reactive power (over-excited); SHALL be a positive value between 0.0 (typically &amp;gt; 0.7) and 1.0, inclusive. SHALL be &amp;gt;= rtgMinPFOverExcited (default).', json_schema_extra={'xml': 'element'})
    setMinPFUnderExcited: PowerFactor | None = Field(default=None, description='Set minimum Power Factor displacement limit of the DER when absorbing reactive power (under-excited); SHALL be a positive value between 0.0 (typically &amp;gt; 0.7) and 1.0, inclusive. If present, SHALL be &amp;gt;= rtgMinPFUnderExcited (default). If absent, defaults to setMinPFOverExcited.', json_schema_extra={'xml': 'element'})
    setMinV: VoltageRMS | None = Field(default=None, description='AC voltage minimum setting.', json_schema_extra={'xml': 'element'})
    setSoftGradW: int | None = Field(default=None, description='Set soft-start rate of change (soft-start ramp rate) of active power output due to command or internal action, defined in %setWMax / second. Resolution is in hundredths of a percent/second. A value of 0 means there is no limit. Interpreted as a percentage change in output capability limit per second when used as a ramp rate.', json_schema_extra={'xml': 'element'})
    setVNom: VoltageRMS | None = Field(default=None, description='AC voltage nominal setting.', json_schema_extra={'xml': 'element'})
    setVRef: VoltageRMS | None = Field(default=None, description='The nominal AC voltage (RMS) at the reference point.', json_schema_extra={'xml': 'element'})
    setVRefOfs: VoltageRMS | None = Field(default=None, description="The nominal AC voltage (RMS) offset between the DER's electrical connection point and the reference point.", json_schema_extra={'xml': 'element'})
    updatedTime: int | None = Field(default=None, description='Specifies the time at which the DER information was last updated.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    DERSettings_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


