class FileStatus(Resource):
    """This object provides status of device file load and activation operations. " """

    activateTime: int | None = Field(default=None, description='Date/time at which this File, referred to by FileLink, will be activated. Omission of or presence and value of this element SHALL exactly match omission or presence and value of the activateTime element from the File resource.', json_schema_extra={'xml': 'element', 'wrapper': 'TimeType'})
    FileLink: _T_FileLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    loadPercent: int | None = Field(default=None, description='This element SHALL be set to the percentage of the file, indicated by FileLink, that was loaded during the latest load attempt. This value SHALL be reset to 0 each time a load attempt is started for the File indicated by FileLink. This value SHALL be increased when an LD receives HTTP response containing file content. This value SHALL be set to 100 when the full content of the file has been received by the LD', json_schema_extra={'xml': 'element', 'required': True})
    nextRequestAttempt: int | None = Field(default=None, description='This element SHALL be set to the time at which the LD will issue its next GET request for file content from the File indicated by FileLink', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    request503Count: int | None = Field(default=None, description='This value SHALL be reset to 0 when FileLink is first pointed at a new File. This value SHALL be incremented each time an LD receives a 503 error from the FS.', json_schema_extra={'xml': 'element', 'required': True})
    requestFailCount: int | None = Field(default=None, description='This value SHALL be reset to 0 when FileLink is first pointed at a new File. This value SHALL be incremented each time a GET request for file content failed. 503 errors SHALL be excluded from this counter.', json_schema_extra={'xml': 'element', 'required': True})
    status: int | None = Field(default=None, description='Current loading status of the file indicated by FileLink. This element SHALL be set to one of the following values: 0 - No load operation in progress 1 - File load in progress (first request for file content has been issued by LD) 2 - File load failed 3 - File loaded successfully (full content of file has been received by the LD), signature verification in progress 4 - File signature verification failed 5 - File signature verified, waiting to activate file. 6 - File activation failed 7 - File activation in progress 8 - File activated successfully (this state may not be reached/persisted through an image activation) 9-255 - Reserved for future use.', json_schema_extra={'xml': 'element', 'required': True})
    statusTime: int | None = Field(default=None, description='This element SHALL be set to the time at which file status transitioned to the value indicated in the status element.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    FileStatus_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    pollRate: int | None = Field(default=None, description='The default polling rate for this function set (this resource and all resources below), in seconds. If not specified, a default of 900 seconds (15 minutes) is used. Clients SHOULD poll the resources of this function set every pollRate seconds.', json_schema_extra={'xml': 'attribute'})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


class FlowReservationRequest(IdentifiedObject):
    """Used to request flow transactions.  Client EndDevices submit a request for charging or discharging from the server. The server creates an associated FlowReservationResponse containing the charging parameters and interval to provide a lower aggregated demand at the premises, or within a larger part of the distribution system. " """

    creationTime: int | None = Field(default=None, description='The time at which the request was created.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    durationRequested: int | None = Field(default=None, description='A value that is calculated by the storage device that defines the minimum duration, in seconds, that it will take to complete the actual flow transaction, including any ramp times and conditioning times, if applicable.', json_schema_extra={'xml': 'element'})
    energyRequested: SignedRealEnergy | None = Field(default=None, description='Indicates the total amount of energy, in Watt-Hours, requested to be transferred between the storage device and the electric power system. Positive values indicate charging and negative values indicate discharging. This sign convention is different than for the DER function where discharging is positive. Note that the energyRequestNow attribute in the PowerStatus Object must always represent a charging solution and it is not allowed to have a negative value.', json_schema_extra={'xml': 'element', 'required': True})
    intervalRequested: DateTimeInterval | None = Field(default=None, description='The time window during which the flow reservation is needed. For example, if an electric vehicle is set with a 7:00 AM time charge is needed, and price drops to the lowest tier at 11:00 PM, then this window would likely be from 11:00 PM until 7:00 AM.', json_schema_extra={'xml': 'element', 'required': True})
    powerRequested: ActivePower | None = Field(default=None, description='Indicates the sustained level of power, in Watts, that is requested. For charging this is calculated by the storage device and it represents the charging system capability (which for an electric vehicle must also account for any power limitations due to the EVSE control pilot). For discharging, a lower value than the inverter capability can be used as a target.', json_schema_extra={'xml': 'element', 'required': True})
    RequestStatus: _T_RequestStatus | None = Field(default=None, json_schema_extra={'xml': 'element', 'required': True})
    FlowReservationRequest_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


