class LoadShedAvailability(Resource):
    """Indicates current consumption status and ability to shed load. " """

    availabilityDuration: int | None = Field(default=None, description='Indicates for how many seconds the consuming device will be able to reduce consumption at the maximum response level.', json_schema_extra={'xml': 'element'})
    DemandResponseProgramLink: _T_DemandResponseProgramLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    sheddablePercent: int | None = Field(default=None, description='Maximum percent of current operating load that is estimated to be sheddable.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCent'})
    sheddablePower: ActivePower | None = Field(default=None, description='Maximum amount of current operating load that is estimated to be sheddable, in Watts.', json_schema_extra={'xml': 'element'})
    LoadShedAvailability_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


