class Notification(SubscriptionBase):
    """Holds the information related to a client subscription to receive updates to a resource automatically.  The actual resources may be passed in the Notification by specifying a specific xsi:type for the Resource and passing the full representation. " """

    createdDateTime: int | None = Field(default=None, description='The date and time that the Notification was created.', json_schema_extra={'xml': 'element', 'wrapper': 'TimeType'})
    newResourceURI: str | None = Field(default=None, description='The new location of the resource, if moved. This attribute SHALL be a fully-qualified absolute URI, not a relative reference.', json_schema_extra={'xml': 'element'})
    Resource: _T_Resource | None = Field(default=None, json_schema_extra={'xml': 'element'})
    status: int | None = Field(default=None, description='0 = Default Status 1 = Subscription canceled, no additional information 2 = Subscription canceled, resource moved 3 = Subscription canceled, resource definition changed (e.g., a new version of IEEE 2030.5) 4 = Subscription canceled, resource deleted All other values reserved.', json_schema_extra={'xml': 'element', 'required': True})
    subscriptionURI: str | None = Field(default=None, description='The subscription from which this notification was triggered. This attribute SHALL be a fully-qualified absolute URI, not a relative reference.', json_schema_extra={'xml': 'element', 'required': True})
    Notification_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


class PowerStatus(Resource):
    """Contains the status of the device's power sources. " """

    batteryStatus: int | None = Field(default=None, description='Battery system status 0 = unknown 1 = normal (more than LowChargeThreshold remaining) 2 = low (less than LowChargeThreshold remaining) 3 = depleted (0% charge remaining) 4 = not applicable (mains powered only)', json_schema_extra={'xml': 'element', 'required': True})
    changedTime: int | None = Field(default=None, description='The time at which the reported values were recorded.', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'TimeType'})
    currentPowerSource: int | None = Field(default=None, description='This value will be fixed for devices powered by a single source. This value may change for devices able to transition between multiple power sources (mains to battery backup, etc.).', json_schema_extra={'xml': 'element', 'required': True, 'wrapper': 'PowerSourceType'})
    estimatedChargeRemaining: int | None = Field(default=None, description='Estimate of remaining battery charge as a percent of full charge.', json_schema_extra={'xml': 'element', 'wrapper': 'PerCent'})
    estimatedTimeRemaining: int | None = Field(default=None, description='Estimated time (in seconds) to total battery charge depletion (under current load)', json_schema_extra={'xml': 'element'})
    PEVInfo: _T_PEVInfo | None = Field(default=None, json_schema_extra={'xml': 'element'})
    sessionTimeOnBattery: int | None = Field(default=None, description='If the device has a battery, this is the time since the device last switched to battery power, or the time since the device was restarted, whichever is less, in seconds.', json_schema_extra={'xml': 'element'})
    totalTimeOnBattery: int | None = Field(default=None, description='If the device has a battery, this is the total time the device has been on battery power, in seconds. It may be reset when the battery is replaced.', json_schema_extra={'xml': 'element'})
    PowerStatus_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    pollRate: int | None = Field(default=None, description='The default polling rate for this function set (this resource and all resources below), in seconds. If not specified, a default of 900 seconds (15 minutes) is used. Clients SHOULD poll the resources of this function set every pollRate seconds.', json_schema_extra={'xml': 'attribute'})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


