class Subscription(SubscriptionBase):
    """Holds the information related to a client subscription to receive updates to a resource automatically. " """

    Condition: _T_Condition | None = Field(default=None, json_schema_extra={'xml': 'element'})
    encoding: int | None = Field(default=None, description='0 - application/sep+xml 1 - application/sep-exi 2-255 - reserved', json_schema_extra={'xml': 'element', 'required': True})
    level: str | None = Field(default=None, description='Contains the preferred schema and extensibility level indication such as "+S2"', max_length=16, json_schema_extra={'xml': 'element', 'required': True, 'max_length': 16})
    limit: int | None = Field(default=None, description='This element is used to indicate the maximum number of list items that should be included in a notification when the subscribed resource changes. This limit is meant to be functionally equivalent to the ‘limit’ query string parameter, but applies to both list resources as well as other resources. For list resources, if a limit of ‘0’ is specified, then notifications SHALL contain a list resource with results=’0’ (equivalent to a simple change notification). For list resources, if a limit greater than ‘0’ is specified, then notifications SHALL contain a list resource with results equal to the limit specified (or less, should the list contain fewer items than the limit specified or should the server be unable to provide the requested number of items for any reason) and follow the same rules for list resources (e.g., ordering). For non-list resources, if a limit of ‘0’ is specified, then notifications SHALL NOT contain a resource representation (equivalent to a simple change notification). For non-list resources, if a limit greater than ‘0’ is specified, then notifications SHALL contain the representation of the changed resource.', json_schema_extra={'xml': 'element', 'required': True})
    notificationURI: str | None = Field(default=None, description='The resource to which to post the notifications about the requested subscribed resource. Because this URI will exist on a server other than the one being POSTed to, this attribute SHALL be a fully-qualified absolute URI, not a relative reference.', json_schema_extra={'xml': 'element', 'required': True})
    Subscription_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


