class RateComponent(IdentifiedObject):
    """Specifies the applicable charges for a single component of the rate, which could be generation price or consumption price, for example. " """

    ActiveTimeTariffIntervalListLink: _T_ActiveTimeTariffIntervalListLink | None = Field(default=None, json_schema_extra={'xml': 'element'})
    flowRateEndLimit: UnitValueType | None = Field(default=None, description='Specifies the maximum flow rate (e.g. kW for electricity) for which this RateComponent applies, for the usage point and given rate / tariff. In combination with flowRateStartLimit, allows a service provider to define the demand or output characteristics for the particular tariff design. If a server includes the flowRateEndLimit attribute, then it SHALL also include flowRateStartLimit attribute. For example, a service provider’s tariff limits customers to 20 kWs of demand for the given rate structure. Above this threshold (from 20-50 kWs), there are different demand charges per unit of consumption. The service provider can use flowRateStartLimit and flowRateEndLimit to describe the demand characteristics of the different rates. Similarly, these attributes can be used to describe limits on premises DERs that might be producing a commodity and sending it back into the distribution network. Note: At the time of writing, service provider tariffs with demand-based components were not originally identified as being in scope, and service provider tariffs vary widely in their use of demand components and the method for computing charges. It is expected that industry groups (e.g., OpenSG) will document requirements in the future that the IEEE 2030.5 community can then use as source material for the next version of IEEE 2030.5.', json_schema_extra={'xml': 'element'})
    flowRateStartLimit: UnitValueType | None = Field(default=None, description='Specifies the minimum flow rate (e.g., kW for electricity) for which this RateComponent applies, for the usage point and given rate / tariff. In combination with flowRateEndLimit, allows a service provider to define the demand or output characteristics for the particular tariff design. If a server includes the flowRateStartLimit attribute, then it SHALL also include flowRateEndLimit attribute.', json_schema_extra={'xml': 'element'})
    ReadingTypeLink: _T_ReadingTypeLink | None = Field(default=None, description='Provides indication of the ReadingType with which this price is associated.', json_schema_extra={'xml': 'element', 'required': True})
    roleFlags: str | None = Field(default=None, description='Specifies the roles that this usage point has been assigned.', json_schema_extra={'xml': 'element', 'required': True, 'format': 'base16', 'wrapper': 'RoleFlagsType'})
    TimeTariffIntervalListLink: _T_TimeTariffIntervalListLink | None = Field(default=None, json_schema_extra={'xml': 'element', 'required': True})
    RateComponent_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
    schemaVer: str | None = Field(default=None, description='The schema version used. All XML payloads SHALL include a schemaVer attribute in the top- level XML element equal to the version of the IEEE 2030.5 schema (IEEE Std 2030.5 supplemental material) used (e.g., schemaVer="2.2"). It should be noted that previous revisions of IEEE 2030.5 did not require this schemaVer attribute.', json_schema_extra={'xml': 'attribute'})


