    linkLayerType: int | None = Field(default=None, description='Specifies the type of link layer interface associated with the IPInterface. Values are below. 0 = Unspecified 1 = IEEE 802.3 (Ethernet) 2 = IEEE 802.11 (WLAN) 3 = IEEE 802.15 (PAN) 4 = IEEE 1901 (PLC) All other values reserved.', json_schema_extra={'xml': 'element', 'required': True})
    LLAckNotRx: int | None = Field(default=None, description='Number of times an ACK was not received for a frame transmitted (when ACK was requested).', json_schema_extra={'xml': 'element'})
    LLCSMAFail: int | None = Field(default=None, description='Number of times CSMA failed.', json_schema_extra={'xml': 'element'})
    LLFramesDropRx: int | None = Field(default=None, description='Number of dropped receive frames.', json_schema_extra={'xml': 'element'})
    LLFramesDropTx: int | None = Field(default=None, description='Number of dropped transmit frames.', json_schema_extra={'xml': 'element'})
    LLFramesRx: int | None = Field(default=None, description='Number of link layer frames received.', json_schema_extra={'xml': 'element'})
    LLFramesTx: int | None = Field(default=None, description='Number of link layer frames transmitted.', json_schema_extra={'xml': 'element'})
    LLMediaAccessFail: int | None = Field(default=None, description='Number of times access to media failed.', json_schema_extra={'xml': 'element'})
    LLOctetsRx: int | None = Field(default=None, description='Number of Bytes received.', json_schema_extra={'xml': 'element'})
    LLOctetsTx: int | None = Field(default=None, description='Number of Bytes transmitted.', json_schema_extra={'xml': 'element'})
    LLRetryCount: int | None = Field(default=None, description='Number of MAC transmit retries.', json_schema_extra={'xml': 'element'})
    LLSecurityErrorRx: int | None = Field(default=None, description='Number of receive security errors.', json_schema_extra={'xml': 'element'})
    loWPAN: _T_loWPAN | None = Field(default=None, json_schema_extra={'xml': 'element'})
    LLInterface_r2_3: Revision2_3Type | None = Field(default=None, json_schema_extra={'xml': 'element', 'revision_marker': True})
